/* LOST SIGNAL service worker — offline play (generated by vite.config.ts at build time). */
const VERSION = '__VERSION__';
const CORE = __CORE__;            // app shell: html, js, css, wasm, catalog, textures
const PACKS = __PACKS__;          // { '512': [...models], '1k': [...models] }
const CORE_CACHE = `ls-core-${VERSION}`;
const MODEL_CACHE = 'ls-models-v1'; // models are named by content; kept across versions, pruned below

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(CORE_CACHE);
    await c.addAll(CORE.map((u) => new Request(u, { cache: 'reload' })));
    self.skipWaiting();
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('ls-core-') && k !== CORE_CACHE) await caches.delete(k);
    // drop models that are no longer part of the game
    const keep = new Set([...PACKS['512'], ...PACKS['1k']].map((u) => new URL(u, self.registration.scope).href));
    const mc = await caches.open(MODEL_CACHE);
    for (const req of await mc.keys()) if (!keep.has(req.url)) await mc.delete(req);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== location.origin || url.pathname.startsWith('/socket.io') || url.pathname === '/health') return;
  if (req.mode === 'navigate') {
    // network first (fresh version when online), cached shell when the Wi-Fi is gone
    e.respondWith(fetch(req).catch(async () => (await caches.match('./index.html', { ignoreSearch: true })) ?? (await caches.match(req, { ignoreSearch: true })) ?? Response.error()));
    return;
  }
  e.respondWith((async () => {
    const hit = await caches.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res.ok) {
        const isModel = /\.glb$/.test(url.pathname);
        const c = await caches.open(isModel ? MODEL_CACHE : CORE_CACHE);
        c.put(req, res.clone());
      }
      return res;
    } catch {
      return Response.error();
    }
  })());
});

/** "Download for offline": fetch every model of one quality tier, reporting progress. */
self.addEventListener('message', (e) => {
  const msg = e.data || {};
  if (msg.type === 'status' || msg.type === 'download') {
    e.waitUntil((async () => {
      const list = PACKS[msg.tier] || PACKS['512'];
      const mc = await caches.open(MODEL_CACHE);
      let done = 0;
      const missing = [];
      for (const u of list) { if (await mc.match(u)) done++; else missing.push(u); }
      const post = (extra) => e.source && e.source.postMessage({ type: 'offline', tier: msg.tier, done, total: list.length, version: VERSION, ...extra });
      post({});
      if (msg.type !== 'download') return;
      for (const u of missing) {
        try { const r = await fetch(u); if (r.ok) { await mc.put(u, r); done++; } } catch { post({ error: true }); return; }
        if (done % 4 === 0) post({});
      }
      post({ finished: true });
    })());
  }
});
